import { cmdImport, cmdReadings, CSV_HEADER } from './src/commands.ts';
import { cmdDaily } from './src/report.ts';
import { cmdAck, cmdAlerts, cmdEvaluate, cmdRuleCreate, cmdRuleList } from './src/alerts.ts';
import { cmdGroupConfigure, cmdGroupDaily, cmdGroupHistory } from './src/groups.ts';
import { parseIso8601, parseUtcDate } from './src/time.ts';
import { parseKwh } from './src/value.ts';

const name = 'meterwatch';

const help = `${name}

建筑能耗监测:本地累计电表读数导入与消耗核查。

Usage:
  node app.ts                       显示本帮助
  node app.ts --help | -h           显示本帮助
  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
  node app.ts readings [筛选...]    查询读数、区间与消耗
  node app.ts daily --from <iso> --to <iso> [--device <id>...]
                                    按 UTC 自然日核查能耗的只读日报
  node app.ts rule create --id <id> --device <设备> --threshold <kWh>
                                    创建每日能耗阈值告警规则
  node app.ts rule list             查看全部告警规则
  node app.ts evaluate --rule <id> --from <日期> --to <日期>
                                    评估规则在连续完整 UTC 日期上的超限情况
  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
                                    查询规则的告警历史(只读)
  node app.ts ack <告警标识>         确认告警
  node app.ts group configure --id <id> --at <iso> --device <id>...
                                    配置分组成员版本(首次配置即建立分组)
  node app.ts group history --id <id>
                                    查看分组成员版本历史(只读)
  node app.ts group daily --id <id> --from <iso> --to <iso>
                                    按当时生效成员的分组能耗日报(只读)

筛选(readings):
  --device <id>     只显示指定设备(可重复使用,区分大小写)
  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
  --to <iso8601>    结束时刻(不含)
  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
  (如 +08:00);起点不早于终点时拒绝查询。

日报(daily):
  --from <iso8601>  起始时刻(含),必填
  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
  日期按 UTC 零点划分,首尾日期只统计与查询范围重叠的部分。
  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
  孤立读数时段为未知,不外推。每天输出估算消耗与有效/异常/未知覆盖秒数
  (三者之和等于该天查询时长);存在未知或异常覆盖时日报标记为不完整。
  日报只读,不写入数据。

分组(group configure / history / daily):
  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
  与 --to(不含)必填且起点必须更早,按 UTC 自然日切分、按当时生效成员
  计算,首个版本生效前记为未知;每个时段只有全部生效成员均处于非下降读数
  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
  切换均不重置分摊起点,拆开查询相加一致。每天显示生效成员及其时段、估算
  消耗与有效/异常/未知秒数(三者之和等于当天查询时长);有异常或未知标为
  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。

告警规则(rule / evaluate / alerts / ack):
  规则标识非空唯一,绑定的设备必须已有存储读数(去首尾空白、区分大小写);
  阈值非负、最多三位小数 kWh;创建后设备与阈值固定。相同标识等价参数重试
  成功且不重复创建,异参重试报冲突。
  evaluate 的 --from/--to 为 YYYY-MM-DD 的 UTC 日期,起日含、止日不含,
  起日必须更早。评估口径与 daily 相同:仅全天有效覆盖的日期可判定,消耗
  严格大于阈值才超限(等于为正常);有未知或下降覆盖的日期不可判定,不触发
  也不恢复。每个规则每个日期独立跟踪:首次超限创建带唯一标识的未确认告警,
  重复超限保留原标识;完整评估正常才记录恢复;恢复后再超限创建新的未确认
  告警,旧记录保留,原确认不转移。批量日期评估要么全部提交要么不提交。
  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
  不改变超限或恢复状态。alerts 按规则和日期展示消耗或不可判定原因、各次
  告警的标识、检测状态、确认状态及触发/恢复/确认的处理顺序;省略日期范围
  时展示有告警记录的全部日期。导入不自动评估,补导后需显式重评。

CSV 格式:
  表头: ${CSV_HEADER}
  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
           范围,任意大的十进制值都精确保存,如 9007199254740.991)
  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。

数值精度:
  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
  和显示全程精确,输出固定三位小数,不使用科学计数法。
  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。

数据位置:
  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json)
  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)

退出码: 0 成功;1 数据或读写错误;2 参数错误`;

function usageError(message: string): number {
  console.error(`${name}: ${message}`);
  console.error(`用法见 'node app.ts --help'`);
  return 2;
}

interface ParsedOptions {
  devices: string[];
  from?: number;
  to?: number;
}

/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
function parseOptions(rest: string[]): ParsedOptions | string {
  const devices: string[] = [];
  let from: number | undefined;
  let to: number | undefined;
  for (let i = 0; i < rest.length; i++) {
    let opt = rest[i];
    let value: string | undefined;
    const eq = opt.indexOf('=');
    if (opt.startsWith('--') && eq !== -1) {
      value = opt.slice(eq + 1);
      opt = opt.slice(0, eq);
    } else if (opt.startsWith('--')) {
      value = rest[i + 1];
      if (value === undefined) return `选项 '${opt}' 缺少值`;
      i++;
    } else {
      return `无法识别的参数 '${opt}'`;
    }
    if (opt === '--device') {
      if (value.trim() === '') return "'--device' 的值不能为空";
      devices.push(value);
    } else if (opt === '--from' || opt === '--to') {
      const ts = parseIso8601(value.trim());
      if (ts === null) {
        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
      }
      if (opt === '--from') from = ts;
      else to = ts;
    } else {
      return `无法识别的选项 '${opt}'`;
    }
  }
  return { devices, from, to };
}

/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
  const out = new Map<string, string[]>();
  for (let i = 0; i < rest.length; i++) {
    let opt = rest[i];
    let value: string | undefined;
    const eq = opt.indexOf('=');
    if (opt.startsWith('--') && eq !== -1) {
      value = opt.slice(eq + 1);
      opt = opt.slice(0, eq);
    } else if (opt.startsWith('--')) {
      value = rest[i + 1];
      if (value === undefined) return `选项 '${opt}' 缺少值`;
      i++;
    } else {
      return `无法识别的参数 '${opt}'`;
    }
    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
    const list = out.get(opt);
    if (list) list.push(value);
    else out.set(opt, [value]);
  }
  return out;
}

/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
function oneFlag(flags: Map<string, string[]>, name: string): string | null {
  const list = flags.get(name);
  if (!list || list.length !== 1) return null;
  return list[0];
}

/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
function dateFlag(value: string, label: string): number | string {
  const ts = parseUtcDate(value.trim());
  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
  return ts;
}

function cmdRule(rest: string[]): number {
  const [sub, ...subrest] = rest;
  if (sub === 'list') {
    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
    return cmdRuleList();
  }
  if (sub === 'create') {
    const flags = parseFlags(subrest, ['--id', '--device', '--threshold']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const deviceRaw = oneFlag(flags, '--device');
    const thresholdRaw = oneFlag(flags, '--threshold');
    if (idRaw === null || deviceRaw === null || thresholdRaw === null) {
      return usageError("'rule create' 需要 --id、--device、--threshold 各恰好一个");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('规则标识不能为空');
    const device = deviceRaw.trim();
    if (device === '') return usageError("'--device' 的值不能为空");
    const thresholdMilli = parseKwh(thresholdRaw.trim());
    if (thresholdMilli === null) {
      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
    }
    return cmdRuleCreate({ id, device, thresholdMilli });
  }
  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
  return usageError(`无法识别的 rule 子命令 '${sub}'`);
}

function cmdEvaluateEntry(rest: string[]): number {
  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
  if (typeof flags === 'string') return usageError(flags);
  const ruleRaw = oneFlag(flags, '--rule');
  const fromRaw = oneFlag(flags, '--from');
  const toRaw = oneFlag(flags, '--to');
  if (ruleRaw === null || fromRaw === null || toRaw === null) {
    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
  }
  const ruleId = ruleRaw.trim();
  if (ruleId === '') return usageError('规则标识不能为空');
  const from = dateFlag(fromRaw, '起始日期');
  if (typeof from === 'string') return usageError(from);
  const to = dateFlag(toRaw, '结束日期');
  if (typeof to === 'string') return usageError(to);
  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
  return cmdEvaluate({ ruleId, from, to });
}

function cmdAlertsEntry(rest: string[]): number {
  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
  if (typeof flags === 'string') return usageError(flags);
  const ruleRaw = oneFlag(flags, '--rule');
  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
  const ruleId = ruleRaw.trim();
  if (ruleId === '') return usageError('规则标识不能为空');
  const fromList = flags.get('--from');
  const toList = flags.get('--to');
  if ((fromList !== undefined) !== (toList !== undefined)) {
    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
  }
  let from: number | undefined;
  let to: number | undefined;
  if (fromList !== undefined) {
    const fromRaw = oneFlag(flags, '--from');
    const toRaw = oneFlag(flags, '--to');
    if (fromRaw === null || toRaw === null) {
      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
    }
    const fromParsed = dateFlag(fromRaw, '起始日期');
    if (typeof fromParsed === 'string') return usageError(fromParsed);
    const toParsed = dateFlag(toRaw, '结束日期');
    if (typeof toParsed === 'string') return usageError(toParsed);
    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
    from = fromParsed;
    to = toParsed;
  }
  return cmdAlerts({ ruleId, from, to });
}

function cmdGroup(rest: string[]): number {
  const [sub, ...subrest] = rest;
  if (sub === 'configure') {
    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const atRaw = oneFlag(flags, '--at');
    const deviceList = flags.get('--device') ?? [];
    if (idRaw === null || atRaw === null) {
      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
    }
    if (deviceList.length === 0) {
      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    const at = parseIso8601(atRaw.trim());
    if (at === null) {
      return usageError(
        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
      );
    }
    const members: string[] = [];
    for (const d of deviceList) {
      const m = d.trim();
      if (m === '') return usageError("'--device' 的值不能为空");
      members.push(m);
    }
    return cmdGroupConfigure({ id, at, members });
  }
  if (sub === 'history') {
    const flags = parseFlags(subrest, ['--id']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    return cmdGroupHistory({ id });
  }
  if (sub === 'daily') {
    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const fromRaw = oneFlag(flags, '--from');
    const toRaw = oneFlag(flags, '--to');
    if (idRaw === null || fromRaw === null || toRaw === null) {
      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    const from = parseIso8601(fromRaw.trim());
    if (from === null) {
      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
    }
    const to = parseIso8601(toRaw.trim());
    if (to === null) {
      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
    }
    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
    return cmdGroupDaily({ id, from, to });
  }
  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
  return usageError(`无法识别的 group 子命令 '${sub}'`);
}

function main(args: string[]): number {
  if (args.length === 0) {
    console.log(help);
    return 0;
  }
  const [cmd, ...rest] = args;
  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
    console.log(help);
    return 0;
  }

  if (cmd === 'import') {
    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
    return cmdImport(rest[0]);
  }

  if (cmd === 'readings') {
    const parsed = parseOptions(rest);
    if (typeof parsed === 'string') return usageError(parsed);
    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
      return usageError('查询起点必须早于终点(--from < --to)');
    }
    return cmdReadings(parsed);
  }

  if (cmd === 'daily') {
    const parsed = parseOptions(rest);
    if (typeof parsed === 'string') return usageError(parsed);
    if (parsed.from === undefined || parsed.to === undefined) {
      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
    }
    if (parsed.from >= parsed.to) {
      return usageError('查询起点必须早于终点(--from < --to)');
    }
    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
  }

  if (cmd === 'rule') return cmdRule(rest);
  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
  if (cmd === 'alerts') return cmdAlertsEntry(rest);
  if (cmd === 'group') return cmdGroup(rest);

  if (cmd === 'ack') {
    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
    const alertId = rest[0].trim();
    if (alertId === '') return usageError('告警标识不能为空');
    return cmdAck(alertId);
  }

  return usageError(`无法识别的参数 '${cmd}'`);
}

process.exitCode = main(process.argv.slice(2));

content.content:
1	// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
2	//
3	// - 规则由使用者指定非空唯一标识,绑定一个已有设备与非负、最多三位小数的
4	//   kWh 阈值;创建后设备与阈值固定。相同标识等价参数重试成功且不重复创建,
5	//   异参重试报冲突。
6	// - 评估针对连续完整 UTC 日期(起日含、止日不含),复用 daily 的完整时序、
7	//   均匀分摊与累计比例向下取整口径;仅全天有效覆盖的日期可判定,消耗严格
8	//   大于阈值才超限,等于阈值视为正常;有未知或下降覆盖时不可判定,不触发
9	//   也不恢复;零增长是有效数据。
10	// - 每条规则的每个日期独立跟踪:首次判定超限创建带唯一标识的未确认告警,
11	//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
12	//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
13	// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
14	//   改变超限或恢复状态。
15	// - 规则与历史存于数据目录的 alerts.json(与 readings.json 相互独立,导入
16	//   不触碰本文件,也不会自动评估)。创建、评估、确认都先在内存完成全部计算
17	//   再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确报错,
18	//   绝不当作空库。
19	
20	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
21	import { dirname } from 'node:path';
22	import {
23	  alertFilePath,
24	  dataFilePath,
25	  loadStore,
26	  parseStoredMilli,
27	  StoreError,
28	  type Reading,
29	} from './store.ts';
30	import { computeDay, DAY_SECONDS } from './report.ts';
31	import { formatIsoUtc, parseIso8601 } from './time.ts';
32	import { formatKwh } from './value.ts';
33	
34	export interface AlertRule {
35	  /** 规则标识(非空、唯一,已去首尾空白)。 */
36	  id: string;
37	  /** 绑定设备(已去首尾空白,区分大小写),创建后固定。 */
38	  device: string;
39	  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
40	  thresholdMilli: bigint;
41	}
42	
43	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
44	
45	export interface AlertEvent {
46	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
47	  seq: number;
48	  type: AlertEventType;
49	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
50	  consumptionMilli?: string;
51	}
52	
53	export interface AlertRecord {
54	  /** 告警标识,全局唯一。 */
55	  id: string;
56	  ruleId: string;
57	  /** UTC 日期,YYYY-MM-DD。 */
58	  date: string;
59	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
60	  status: 'triggered' | 'recovered';
61	  acknowledged: boolean;
62	  events: AlertEvent[];
63	}
64	
65	interface AlertState {
66	  nextAlertNum: number;
67	  nextEventSeq: number;
68	  rules: AlertRule[];
69	  alerts: AlertRecord[];
70	}
71	
72	function err(message: string): void {
73	  console.error(`meterwatch: ${message}`);
74	}
75	
76	function emptyState(): AlertState {
77	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
78	}
79	
80	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
81	function loadAlertState(path: string): AlertState {
82	  let text: string;
83	  try {
84	    text = readFileSync(path, 'utf8');
85	  } catch (e) {
86	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
87	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
88	  }
89	  let data: unknown;
90	  try {
91	    data = JSON.parse(text);
92	  } catch {
93	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
94	  }
95	  const bad = (what: string): StoreError =>
96	    new StoreError(`storage file ${path} is corrupted (${what})`);
97	  const o = data as Record<string, unknown>;
98	  if (o === null || typeof o !== 'object') throw bad('not an object');
99	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
100	    throw bad('invalid nextAlertNum');
101	  }
102	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
103	    throw bad('invalid nextEventSeq');
104	  }
105	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
106	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
107	
108	  const ruleIds = new Set<string>();
109	  const rules: AlertRule[] = [];
110	  for (const r of o.rules as Array<Record<string, unknown>>) {
111	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
112	    // 按损坏数据拒绝,不猜测原值。
113	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
114	    const ok =
115	      r !== null &&
116	      typeof r === 'object' &&
117	      typeof r.id === 'string' &&
118	      r.id.length > 0 &&
119	      typeof r.device === 'string' &&
120	      r.device.length > 0 &&
121	      thresholdMilli !== null;
122	    if (!ok) throw bad('invalid rule entry');
123	    if (ruleIds.has(r.id as string)) throw bad(`duplicate rule id '${r.id}'`);
124	    ruleIds.add(r.id as string);
125	    rules.push({ id: r.id as string, device: r.device as string, thresholdMilli: thresholdMilli as bigint });
126	  }
127	
128	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
129	  const alertIds = new Set<string>();
130	  for (const a of o.alerts as Array<Record<string, unknown>>) {
131	    const ok =
132	      a !== null &&
133	      typeof a === 'object' &&
134	      typeof a.id === 'string' &&
135	      a.id.length > 0 &&
136	      typeof a.ruleId === 'string' &&
137	      ruleIds.has(a.ruleId) &&
138	      typeof a.date === 'string' &&
139	      DATE_RE.test(a.date) &&
140	      (a.status === 'triggered' || a.status === 'recovered') &&
141	      typeof a.acknowledged === 'boolean' &&
142	      Array.isArray(a.events);
143	    if (!ok) throw bad('invalid alert entry');
144	    if (alertIds.has(a.id as string)) throw bad(`duplicate alert id '${a.id}'`);
145	    alertIds.add(a.id as string);
146	    for (const e of a.events as Array<Record<string, unknown>>) {
147	      const eok =
148	        e !== null &&
149	        typeof e === 'object' &&
150	        Number.isSafeInteger(e.seq) &&
151	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
152	        (e.consumptionMilli === undefined ||
153	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
154	      if (!eok) throw bad('invalid alert event');
155	    }
156	  }
157	  return {
158	    nextAlertNum: o.nextAlertNum as number,
159	    nextEventSeq: o.nextEventSeq as number,
160	    rules,
161	    alerts: o.alerts as unknown as AlertRecord[],
162	  };
163	}
164	
165	/** 原子写入告警存储;失败抛错,原有数据保持不变。 */
166	function saveAlertState(path: string, state: AlertState): void {
167	  mkdirSync(dirname(path), { recursive: true });
168	  const tmp = `${path}.tmp-${process.pid}`;
169	  const body =
170	    JSON.stringify(
171	      {
172	        version: 1,
173	        ...state,
174	        rules: state.rules.map((r) => ({ ...r, thresholdMilli: r.thresholdMilli.toString() })),
175	      },
176	      null,
177	      2,
178	    ) + '\n';
179	  try {
180	    writeFileSync(tmp, body, 'utf8');
181	    renameSync(tmp, path);
182	  } catch (e) {
183	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
184	  }
185	}
186	
187	/**
188	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
189	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
190	 */
191	function deviceSeries(device: string): Reading[] {
192	  const all = loadStore(dataFilePath());
193	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
194	  for (let i = 1; i < series.length; i++) {
195	    if (series[i].ts === series[i - 1].ts) {
196	      throw new StoreError(
197	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
198	      );
199	    }
200	  }
201	  return series;
202	}
203	
204	/** 不可判定原因(未知/异常覆盖秒数)。 */
205	function undecidableReason(stats: { unknown: number; anomaly: number }): string {
206	  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
207	}
208	
209	/**
210	 * 创建规则。相同标识等价参数(同设备、同阈值)重试成功且不重复创建;
211	 * 异参重试报冲突。设备必须已有存储读数。返回进程退出码。
212	 */
213	export function cmdRuleCreate(opts: {
214	  id: string;
215	  device: string;
216	  thresholdMilli: bigint;
217	}): number {
218	  const statePath = alertFilePath();
219	  let state: AlertState;
220	  try {
221	    state = loadAlertState(statePath);
222	  } catch (e) {
223	    if (e instanceof StoreError) {
224	      err(e.message);
225	      return 1;
226	    }
227	    throw e;
228	  }
229	
230	  const existing = state.rules.find((r) => r.id === opts.id);
231	  if (existing) {
232	    if (existing.device === opts.device && existing.thresholdMilli === opts.thresholdMilli) {
233	      console.log(
234	        `rule '${opts.id}' already exists with identical parameters (device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
235	      );
236	      return 0;
237	    }
238	    err(
239	      `rule '${opts.id}' already exists with different parameters ` +
240	        `(stored device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
241	        `got device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
242	    );
243	    return 1;
244	  }
245	
246	  let devices: Set<string>;
247	  try {
248	    devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
249	  } catch (e) {
250	    if (e instanceof StoreError) {
251	      err(e.message);
252	      return 1;
253	    }
254	    throw e;
255	  }
256	  if (!devices.has(opts.device)) {
257	    err(`unknown device '${opts.device}': no stored readings; import readings before creating a rule`);
258	    return 1;
259	  }
260	
261	  state.rules.push({ id: opts.id, device: opts.device, thresholdMilli: opts.thresholdMilli });
262	  try {
263	    saveAlertState(statePath, state);
264	  } catch (e) {
265	    if (e instanceof StoreError) {
266	      err(e.message);
267	      return 1;
268	    }
269	    throw e;
270	  }
271	  console.log(
272	    `rule '${opts.id}' created: device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
273	  );
274	  return 0;
275	}
276	
277	/** 列出全部规则。只读。返回进程退出码。 */
278	export function cmdRuleList(): number {
279	  let state: AlertState;
280	  try {
281	    state = loadAlertState(alertFilePath());
282	  } catch (e) {
283	    if (e instanceof StoreError) {
284	      err(e.message);
285	      return 1;
286	    }
287	    throw e;
288	  }
289	  if (state.rules.length === 0) {
290	    console.log('no rules defined');
291	    return 0;
292	  }
293	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
294	  for (const r of rules) {
295	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
296	    console.log(
297	      `rule ${r.id}  device=${r.device}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
298	    );
299	  }
300	  return 0;
301	}
302	
303	/**
304	 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
305	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交。
306	 * 返回进程退出码。
307	 */
308	export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
309	  const statePath = alertFilePath();
310	  let state: AlertState;
311	  let rule: AlertRule;
312	  let series: Reading[];
313	  try {
314	    state = loadAlertState(statePath);
315	    const found = state.rules.find((r) => r.id === opts.ruleId);
316	    if (!found) {
317	      err(`unknown rule '${opts.ruleId}'`);
318	      return 1;
319	    }
320	    rule = found;
321	    series = deviceSeries(rule.device);
322	  } catch (e) {
323	    if (e instanceof StoreError) {
324	      err(e.message);
325	      return 1;
326	    }
327	    throw e;
328	  }
329	
330	  const threshold = rule.thresholdMilli;
331	  const lines: string[] = [];
332	  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
333	    const date = formatIsoUtc(dayStart).slice(0, 10);
334	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
335	    if (stats.unknown > 0 || stats.anomaly > 0) {
336	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
337	      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
338	      continue;
339	    }
340	    const exceeded = stats.consumption > threshold;
341	    const cmp =
342	      `consumption=${formatKwh(stats.consumption)} kWh ` +
343	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
344	    const open = state.alerts.find(
345	      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
346	    );
347	    if (exceeded) {
348	      if (open) {
349	        // 重复超限:保留原标识,不新增事件。
350	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
351	      } else {
352	        const id = `alert-${state.nextAlertNum++}`;
353	        state.alerts.push({
354	          id,
355	          ruleId: rule.id,
356	          date,
357	          status: 'triggered',
358	          acknowledged: false,
359	          events: [
360	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
361	          ],
362	        });
363	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
364	      }
365	    } else {
366	      if (open) {
367	        open.status = 'recovered';
368	        open.events.push({
369	          seq: state.nextEventSeq++,
370	          type: 'recovered',
371	          consumptionMilli: stats.consumption.toString(),
372	        });
373	        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
374	      } else {
375	        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
376	      }
377	    }
378	  }
379	
380	  try {
381	    saveAlertState(statePath, state);
382	  } catch (e) {
383	    if (e instanceof StoreError) {
384	      err(e.message);
385	      return 1;
386	    }
387	    throw e;
388	  }
389	
390	  console.log(
391	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
392	  );
393	  for (const line of lines) console.log(line);
394	  return 0;
395	}
396	
397	/**
398	 * 查询规则的告警历史。只读,不修改数据。
399	 * 给定日期范围时逐日展示消耗或不可判定原因及各次告警;省略范围时展示
400	 * 有告警记录的全部日期。返回进程退出码。
401	 */
402	export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
403	  let state: AlertState;
404	  let rule: AlertRule;
405	  let series: Reading[];
406	  try {
407	    state = loadAlertState(alertFilePath());
408	    const found = state.rules.find((r) => r.id === opts.ruleId);
409	    if (!found) {
410	      err(`unknown rule '${opts.ruleId}'`);
411	      return 1;
412	    }
413	    rule = found;
414	    series = deviceSeries(rule.device);
415	  } catch (e) {
416	    if (e instanceof StoreError) {
417	      err(e.message);
418	      return 1;
419	    }
420	    throw e;
421	  }
422	
423	  let dayStarts: number[];
424	  if (opts.from !== undefined && opts.to !== undefined) {
425	    dayStarts = [];
426	    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
427	  } else {
428	    const dates = [
429	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
430	    ].sort();
431	    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
432	  }
433	
434	  console.log(
435	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
436	  );
437	  if (dayStarts.length === 0) {
438	    console.log(`  no alerts recorded for rule '${rule.id}'`);
439	    return 0;
440	  }
441	
442	  const threshold = rule.thresholdMilli;
443	  for (const dayStart of dayStarts) {
444	    const date = formatIsoUtc(dayStart).slice(0, 10);
445	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
446	    if (stats.unknown > 0 || stats.anomaly > 0) {
447	      console.log(`  ${date}  ${undecidableReason(stats)}`);
448	    } else {
449	      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
450	      console.log(
451	        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
452	          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
453	      );
454	    }
455	    const alerts = state.alerts
456	      .filter((a) => a.ruleId === rule.id && a.date === date)
457	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
458	    if (alerts.length === 0) {
459	      console.log('    no alerts');
460	      continue;
461	    }
462	    for (const a of alerts) {
463	      console.log(
464	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
465	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
466	      );
467	      const events = a.events
468	        .map((e) => {
469	          const consumption =
470	            e.consumptionMilli !== undefined
471	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
472	              : '';
473	          return `#${e.seq} ${e.type}${consumption}`;
474	        })
475	        .join(', ');
476	      console.log(`      events: ${events}`);
477	    }
478	  }
479	  return 0;
480	}
481	
482	/**
483	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
484	 * 确认不改变超限或恢复状态。返回进程退出码。
485	 */
486	export function cmdAck(alertId: string): number {
487	  const statePath = alertFilePath();
488	  let state: AlertState;
489	  try {
490	    state = loadAlertState(statePath);
491	  } catch (e) {
492	    if (e instanceof StoreError) {
493	      err(e.message);
494	      return 1;
495	    }
496	    throw e;
497	  }
498	  const alert = state.alerts.find((a) => a.id === alertId);
499	  if (!alert) {
500	    err(`unknown alert '${alertId}'`);
501	    return 1;
502	  }
503	  if (alert.acknowledged) {
504	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
505	    return 0;
506	  }
507	  alert.acknowledged = true;
508	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
509	  try {
510	    saveAlertState(statePath, state);
511	  } catch (e) {
512	    if (e instanceof StoreError) {
513	      err(e.message);
514	      return 1;
515	    }
516	    throw e;
517	  }
518	  console.log(
519	    `alert ${alert.id} acknowledged (rule=${alert.ruleId} date=${alert.date} status=${alert.status})`,
520	  );
521	  return 0;
522	}
