input.content:
// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
//
// 规则分两类,由 targetType 区分:
// - device 规则绑定一个已有设备;
// - group 规则绑定一个已有分组标识(不冻结创建时成员,每天按当时生效的成员
//   版本计算,允许日内切换)。
// 设备与分组即使同名也是不同目标;规则标识在两类规则间统一唯一(去首尾空白、
// 区分大小写)。阈值为非负、最多三位小数的 kWh,绑定目标与阈值创建后固定。
// 相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建,异参报冲突。
//
// - 评估针对连续完整 UTC 日期(起日含、止日不含)。设备规则复用 daily 的完整
//   时序、均匀分摊与累计比例向下取整口径;分组规则复用 group daily 的联合覆盖
//   口径:每天按当时生效的成员版本切分时段(允许日内切换),任一成员下降为异常,
//   否则任一成员未知为未知,首个版本生效前为未知;成员切换不重置各设备原读数
//   区间的分摊起点。仅全天有效覆盖的日期可判定,消耗严格大于阈值才超限,等于
//   阈值视为正常;有未知或下降覆盖时不可判定,不触发也不恢复;零增长是有效数据。
// - 每条规则的每个日期独立跟踪:首次判定超限创建全局唯一标识的未确认告警,
//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
//   改变超限或恢复状态。
// - 规则与历史存于数据目录的 alerts.json(与 readings.json、groups.json 相互
//   独立,导入与补录成员版本都不会自动评估)。创建、评估、确认都先在内存完成
//   全部计算再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确
//   报错,绝不当作空库。旧版仅含 device 字段的规则无需手工转换即可继续使用。

import { readFileSync } from 'node:fs';
import {
  alertFilePath,
  dataFilePath,
  groupFilePath,
  loadStore,
  parseStoredMilli,
  StoreError,
  type Reading,
} from './store.ts';
import { computeDay, DAY_SECONDS, type DayStats } from './report.ts';
import { computeGroupSegment, loadGroups, type Group } from './groups.ts';
import { loadCheckedSeriesByDevice } from './groups.ts';
import { formatIsoUtc, parseIso8601 } from './time.ts';
import { formatKwh } from './value.ts';

export type RuleTargetType = 'device' | 'group';

export interface AlertRule {
  /** 规则标识(非空、唯一,已去首尾空白,设备与分组规则间统一唯一)。 */
  id: string;
  /** 目标类型:设备或分组。 */
  targetType: RuleTargetType;
  /** 绑定的设备或分组标识(已去首尾空白,区分大小写),创建后固定。 */
  targetId: string;
  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
  thresholdMilli: bigint;
}

export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';

export interface AlertEvent {
  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
  seq: number;
  type: AlertEventType;
  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
  consumptionMilli?: string;
}

export interface AlertRecord {
  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
  id: string;
  ruleId: string;
  /** UTC 日期,YYYY-MM-DD。 */
  date: string;
  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
  status: 'triggered' | 'recovered';
  acknowledged: boolean;
  events: AlertEvent[];
}

interface AlertState {
  nextAlertNum: number;
  nextEventSeq: number;
  rules: AlertRule[];
  alerts: AlertRecord[];
}

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

function emptyState(): AlertState {
  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
}

/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
  return `${rule.targetType}=${rule.targetId}`;
}

/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
function loadAlertState(path: string): AlertState {
  let text: string;
  try {
    text = readFileSync(path, 'utf8');
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
  }
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
  }
  const bad = (what: string): StoreError =>
    new StoreError(`storage file ${path} is corrupted (${what})`);
  const o = data as Record<string, unknown>;
  if (o === null || typeof o !== 'object') throw bad('not an object');
  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
    throw bad('invalid nextAlertNum');
  }
  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
    throw bad('invalid nextEventSeq');
  }
  if (!Array.isArray(o.rules)) throw bad('missing rules array');
  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');

  const ruleIds = new Set<string>();
  const rules: AlertRule[] = [];
  for (const r of o.rules as Array<Record<string, unknown>>) {
    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
    // 按损坏数据拒绝,不猜测原值。
    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
    if (
      r === null ||
      typeof r !== 'object' ||
      typeof r.id !== 'string' ||
      r.id.length === 0 ||
      thresholdMilli === null
    ) {
      throw bad('invalid rule entry');
    }
    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
    // 读入,已有设备规则无需手工转换即可继续使用。
    let targetType: RuleTargetType;
    let targetId: string;
    if (r.targetType === undefined) {
      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
      targetType = 'device';
      targetId = r.device;
    } else {
      if (r.targetType !== 'device' && r.targetType !== 'group') {
        throw bad(`invalid targetType in rule '${r.id}'`);
      }
      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
        throw bad(`invalid targetId in rule '${r.id}'`);
      }
      targetType = r.targetType;
      targetId = r.targetId;
    }
    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
    ruleIds.add(r.id);
    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint });
  }

  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
  const alertIds = new Set<string>();
  for (const a of o.alerts as Array<Record<string, unknown>>) {
    const ok =
      a !== null &&
      typeof a === 'object' &&
      typeof a.id === 'string' &&
      a.id.length > 0 &&
      typeof a.ruleId === 'string' &&
      ruleIds.has(a.ruleId) &&
      typeof a.date === 'string' &&
      DATE_RE.test(a.date) &&
      (a.status === 'triggered' || a.status === 'recovered') &&
      typeof a.acknowledged === 'boolean' &&
      Array.isArray(a.events) &&
      (a.events as unknown[]).length > 0;
    if (!ok) throw bad('invalid alert entry');
    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
    alertIds.add(a.id);
    const seqs = new Set<number>();
    for (const e of a.events as Array<Record<string, unknown>>) {
      const eok =
        e !== null &&
        typeof e === 'object' &&
        Number.isSafeInteger(e.seq) &&
        (e.seq as number) >= 1 &&
        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
        (e.consumptionMilli === undefined ||
          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
      if (!eok) throw bad('invalid alert event');
      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
      seqs.add(e.seq as number);
    }
  }
  return {
    nextAlertNum: o.nextAlertNum as number,
    nextEventSeq: o.nextEventSeq as number,
    rules,
    alerts: o.alerts as unknown as AlertRecord[],
  };
}

/**
 * 原子写入告警存储;失败抛错,原有数据保持不变。
 * 告警写入不触碰读数与成员版本文件。
 */
function saveAlertState(path: string, state: AlertState): void {
  // 直接复用 store.ts 的原子写入实现风格,内联以保持本文件自包含的错误措辞。
  const { mkdirSync, renameSync, writeFileSync } = require('node:fs') as typeof import('node:fs');
  const { dirname } = require('node:path') as typeof import('node:path');
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}`;
  const body =
    JSON.stringify(
      {
        version: 2,
        ...state,
        rules: state.rules.map((r) => ({
          id: r.id,
          targetType: r.targetType,
          targetId: r.targetId,
          thresholdMilli: r.thresholdMilli.toString(),
        })),
      },
      null,
      2,
    ) + '\n';
  try {
    writeFileSync(tmp, body, 'utf8');
    renameSync(tmp, path);
  } catch (e) {
    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
  }
}

/**
 * 载入读数并取出指定设备的完整时序(按时刻排序)。
 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
 */
function deviceSeries(device: string): Reading[] {
  const all = loadStore(dataFilePath());
  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
  for (let i = 1; i < series.length; i++) {
    if (series[i].ts === series[i - 1].ts) {
      throw new StoreError(
        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
      );
    }
  }
  return series;
}

/**
 * 分组规则的评估环境:绑定分组与全库设备时序。
 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
 */
interface GroupEnv {
  kind: 'group';
  group: Group;
  byDevice: Map<string, Reading[]>;
}

interface DeviceEnv {
  kind: 'device';
  series: Reading[];
}

type RuleEnv = DeviceEnv | GroupEnv;

/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
function prepareEnv(rule: AlertRule): RuleEnv {
  if (rule.targetType === 'device') {
    return { kind: 'device', series: deviceSeries(rule.targetId) };
  }
  const groups = loadGroups(groupFilePath());
  const group = groups.find((g) => g.id === rule.targetId);
  if (!group) {
    throw new StoreError(
      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
    );
  }
  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
  return { kind: 'group', group, byDevice };
}

/** 不可判定原因(未知/异常覆盖秒数)。 */
function undecidableReason(stats: Pick<DayStats, 'unknown' | 'anomaly'>): string {
  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
}

/**
 * 计算规则在完整 UTC 日 [dayStart, dayStart+86400) 上的统计。
 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径。
 */
function computeRuleDay(rule: AlertRule, env: RuleEnv, dayStart: number): DayStats {
  const dayEnd = dayStart + DAY_SECONDS;
  if (env.kind === 'device') {
    return computeDay(env.series, dayStart, dayEnd);
  }
  const stats = computeGroupSegment(env.group.versions, env.byDevice, dayStart, dayEnd);
  return {
    valid: stats.valid,
    anomaly: stats.anomaly,
    unknown: stats.unknown,
    consumption: stats.consumption,
  };
}

/**
 * 创建规则。相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建;
 * 任一不同即报冲突。设备必须已有存储读数;分组必须已配置。返回进程退出码。
 */
export function cmdRuleCreate(opts: {
  id: string;
  targetType: RuleTargetType;
  targetId: string;
  thresholdMilli: bigint;
}): number {
  const statePath = alertFilePath();
  let state: AlertState;
  try {
    state = loadAlertState(statePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  const got = `${opts.targetType}=${opts.targetId}`;
  const existing = state.rules.find((r) => r.id === opts.id);
  if (existing) {
    if (
      existing.targetType === opts.targetType &&
      existing.targetId === opts.targetId &&
      existing.thresholdMilli === opts.thresholdMilli
    ) {
      console.log(
        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
          `threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
      );
      return 0;
    }
    err(
      `rule '${opts.id}' already exists with different parameters ` +
        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
    );
    return 1;
  }

  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
  try {
    if (opts.targetType === 'device') {
      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
      if (!devices.has(opts.targetId)) {
        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
        return 1;
      }
    } else {
      const groups = loadGroups(groupFilePath());
      if (!groups.some((g) => g.id === opts.targetId)) {
        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
        return 1;
      }
    }
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  state.rules.push({
    id: opts.id,
    targetType: opts.targetType,
    targetId: opts.targetId,
    thresholdMilli: opts.thresholdMilli,
  });
  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  console.log(
    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
  );
  return 0;
}

/** 列出全部规则(含目标类型)。只读。返回进程退出码。 */
export function cmdRuleList(): number {
  let state: AlertState;
  try {
    state = loadAlertState(alertFilePath());
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  if (state.rules.length === 0) {
    console.log('no rules defined');
    return 0;
  }
  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  for (const r of rules) {
    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
    console.log(
      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
    );
  }
  return 0;
}

/**
 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
 */
export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
  const statePath = alertFilePath();
  let state: AlertState;
  let rule: AlertRule;
  let env: RuleEnv;
  try {
    state = loadAlertState(statePath);
    const found = state.rules.find((r) => r.id === opts.ruleId);
    if (!found) {
      err(`unknown rule '${opts.ruleId}'`);
      return 1;
    }
    rule = found;
    env = prepareEnv(rule);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
  const alertIds = new Set(state.alerts.map((a) => a.id));

  const threshold = rule.thresholdMilli;
  const lines: string[] = [];
  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
    const date = formatIsoUtc(dayStart).slice(0, 10);
    const stats = computeRuleDay(rule, env, dayStart);
    if (stats.unknown > 0 || stats.anomaly > 0) {
      // 有未知或下降覆盖:不可判定,不触发也不恢复。
      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
      continue;
    }
    const exceeded = stats.consumption > threshold;
    const cmp =
      `consumption=${formatKwh(stats.consumption)} kWh ` +
      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
    const open = state.alerts.find(
      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
    );
    if (exceeded) {
      if (open) {
        // 重复超限:保留原标识,不新增事件。
        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
      } else {
        const id = `alert-${state.nextAlertNum++}`;
        if (alertIds.has(id)) {
          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
          return 1;
        }
        alertIds.add(id);
        state.alerts.push({
          id,
          ruleId: rule.id,
          date,
          status: 'triggered',
          acknowledged: false,
          events: [
            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
          ],
        });
        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
      }
    } else {
      if (open) {
        open.status = 'recovered';
        open.events.push({
          seq: state.nextEventSeq++,
          type: 'recovered',
          consumptionMilli: stats.consumption.toString(),
        });
        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
      } else {
        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
      }
    }
  }

  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  console.log(
    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
  );
  for (const line of lines) console.log(line);
  return 0;
}

/**
 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
 * 给定日期范围时逐日展示当前计算的消耗或不可判定原因及各次告警;省略范围时
 * 展示有告警记录的全部日期。触发/恢复事件中的消耗为评估当时记录,不随后续
 * 数据变化改写。返回进程退出码。
 */
export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
  let state: AlertState;
  let rule: AlertRule;
  let env: RuleEnv;
  try {
    state = loadAlertState(alertFilePath());
    const found = state.rules.find((r) => r.id === opts.ruleId);
    if (!found) {
      err(`unknown rule '${opts.ruleId}'`);
      return 1;
    }
    rule = found;
    env = prepareEnv(rule);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  let dayStarts: number[];
  if (opts.from !== undefined && opts.to !== undefined) {
    dayStarts = [];
    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
  } else {
    const dates = [
      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
    ].sort();
    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
  }

  console.log(
    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
  );
  if (dayStarts.length === 0) {
    console.log(`  no alerts recorded for rule '${rule.id}'`);
    return 0;
  }

  const threshold = rule.thresholdMilli;
  for (const dayStart of dayStarts) {
    const date = formatIsoUtc(dayStart).slice(0, 10);
    const stats = computeRuleDay(rule, env, dayStart);
    if (stats.unknown > 0 || stats.anomaly > 0) {
      console.log(`  ${date}  ${undecidableReason(stats)}`);
    } else {
      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
      console.log(
        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
      );
    }
    const alerts = state.alerts
      .filter((a) => a.ruleId === rule.id && a.date === date)
      .sort((a, b) => a.events[0].seq - b.events[0].seq);
    if (alerts.length === 0) {
      console.log('    no alerts');
      continue;
    }
    for (const a of alerts) {
      console.log(
        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
      );
      const events = a.events
        .map((e) => {
          const consumption =
            e.consumptionMilli !== undefined
              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
              : '';
          return `#${e.seq} ${e.type}${consumption}`;
        })
        .join(', ');
      console.log(`      events: ${events}`);
    }
  }
  return 0;
}

/**
 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
 * 确认不改变超限或恢复状态。返回进程退出码。
 */
export function cmdAck(alertId: string): number {
  const statePath = alertFilePath();
  let state: AlertState;
  try {
    state = loadAlertState(statePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const alert = state.alerts.find((a) => a.id === alertId);
  if (!alert) {
    err(`unknown alert '${alertId}'`);
    return 1;
  }
  if (alert.acknowledged) {
    console.log(`alert ${alert.id} already acknowledged; unchanged`);
    return 0;
  }
  alert.acknowledged = true;
  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const rule = state.rules.find((r) => r.id === alert.ruleId);
  const target = rule ? ` ${targetLabel(rule)}` : '';
  console.log(
    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
  );
  return 0;
}

toolUseResult.content:
// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
//
// 规则分两类,由 targetType 区分:
// - device 规则绑定一个已有设备;
// - group 规则绑定一个已有分组标识(不冻结创建时成员,每天按当时生效的成员
//   版本计算,允许日内切换)。
// 设备与分组即使同名也是不同目标;规则标识在两类规则间统一唯一(去首尾空白、
// 区分大小写)。阈值为非负、最多三位小数的 kWh,绑定目标与阈值创建后固定。
// 相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建,异参报冲突。
//
// - 评估针对连续完整 UTC 日期(起日含、止日不含)。设备规则复用 daily 的完整
//   时序、均匀分摊与累计比例向下取整口径;分组规则复用 group daily 的联合覆盖
//   口径:每天按当时生效的成员版本切分时段(允许日内切换),任一成员下降为异常,
//   否则任一成员未知为未知,首个版本生效前为未知;成员切换不重置各设备原读数
//   区间的分摊起点。仅全天有效覆盖的日期可判定,消耗严格大于阈值才超限,等于
//   阈值视为正常;有未知或下降覆盖时不可判定,不触发也不恢复;零增长是有效数据。
// - 每条规则的每个日期独立跟踪:首次判定超限创建全局唯一标识的未确认告警,
//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
//   改变超限或恢复状态。
// - 规则与历史存于数据目录的 alerts.json(与 readings.json、groups.json 相互
//   独立,导入与补录成员版本都不会自动评估)。创建、评估、确认都先在内存完成
//   全部计算再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确
//   报错,绝不当作空库。旧版仅含 device 字段的规则无需手工转换即可继续使用。

import { readFileSync } from 'node:fs';
import {
  alertFilePath,
  dataFilePath,
  groupFilePath,
  loadStore,
  parseStoredMilli,
  StoreError,
  type Reading,
} from './store.ts';
import { computeDay, DAY_SECONDS, type DayStats } from './report.ts';
import { computeGroupSegment, loadGroups, type Group } from './groups.ts';
import { loadCheckedSeriesByDevice } from './groups.ts';
import { formatIsoUtc, parseIso8601 } from './time.ts';
import { formatKwh } from './value.ts';

export type RuleTargetType = 'device' | 'group';

export interface AlertRule {
  /** 规则标识(非空、唯一,已去首尾空白,设备与分组规则间统一唯一)。 */
  id: string;
  /** 目标类型:设备或分组。 */
  targetType: RuleTargetType;
  /** 绑定的设备或分组标识(已去首尾空白,区分大小写),创建后固定。 */
  targetId: string;
  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
  thresholdMilli: bigint;
}

export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';

export interface AlertEvent {
  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
  seq: number;
  type: AlertEventType;
  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
  consumptionMilli?: string;
}

export interface AlertRecord {
  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
  id: string;
  ruleId: string;
  /** UTC 日期,YYYY-MM-DD。 */
  date: string;
  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
  status: 'triggered' | 'recovered';
  acknowledged: boolean;
  events: AlertEvent[];
}

interface AlertState {
  nextAlertNum: number;
  nextEventSeq: number;
  rules: AlertRule[];
  alerts: AlertRecord[];
}

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

function emptyState(): AlertState {
  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
}

/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
  return `${rule.targetType}=${rule.targetId}`;
}

/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
function loadAlertState(path: string): AlertState {
  let text: string;
  try {
    text = readFileSync(path, 'utf8');
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
  }
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
  }
  const bad = (what: string): StoreError =>
    new StoreError(`storage file ${path} is corrupted (${what})`);
  const o = data as Record<string, unknown>;
  if (o === null || typeof o !== 'object') throw bad('not an object');
  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
    throw bad('invalid nextAlertNum');
  }
  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
    throw bad('invalid nextEventSeq');
  }
  if (!Array.isArray(o.rules)) throw bad('missing rules array');
  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');

  const ruleIds = new Set<string>();
  const rules: AlertRule[] = [];
  for (const r of o.rules as Array<Record<string, unknown>>) {
    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
    // 按损坏数据拒绝,不猜测原值。
    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
    if (
      r === null ||
      typeof r !== 'object' ||
      typeof r.id !== 'string' ||
      r.id.length === 0 ||
      thresholdMilli === null
    ) {
      throw bad('invalid rule entry');
    }
    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
    // 读入,已有设备规则无需手工转换即可继续使用。
    let targetType: RuleTargetType;
    let targetId: string;
    if (r.targetType === undefined) {
      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
      targetType = 'device';
      targetId = r.device;
    } else {
      if (r.targetType !== 'device' && r.targetType !== 'group') {
        throw bad(`invalid targetType in rule '${r.id}'`);
      }
      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
        throw bad(`invalid targetId in rule '${r.id}'`);
      }
      targetType = r.targetType;
      targetId = r.targetId;
    }
    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
    ruleIds.add(r.id);
    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint });
  }

  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
  const alertIds = new Set<string>();
  for (const a of o.alerts as Array<Record<string, unknown>>) {
    const ok =
      a !== null &&
      typeof a === 'object' &&
      typeof a.id === 'string' &&
      a.id.length > 0 &&
      typeof a.ruleId === 'string' &&
      ruleIds.has(a.ruleId) &&
      typeof a.date === 'string' &&
      DATE_RE.test(a.date) &&
      (a.status === 'triggered' || a.status === 'recovered') &&
      typeof a.acknowledged === 'boolean' &&
      Array.isArray(a.events) &&
      (a.events as unknown[]).length > 0;
    if (!ok) throw bad('invalid alert entry');
    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
    alertIds.add(a.id);
    const seqs = new Set<number>();
    for (const e of a.events as Array<Record<string, unknown>>) {
      const eok =
        e !== null &&
        typeof e === 'object' &&
        Number.isSafeInteger(e.seq) &&
        (e.seq as number) >= 1 &&
        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
        (e.consumptionMilli === undefined ||
          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
      if (!eok) throw bad('invalid alert event');
      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
      seqs.add(e.seq as number);
    }
  }
  return {
    nextAlertNum: o.nextAlertNum as number,
    nextEventSeq: o.nextEventSeq as number,
    rules,
    alerts: o.alerts as unknown as AlertRecord[],
  };
}

/**
 * 原子写入告警存储;失败抛错,原有数据保持不变。
 * 告警写入不触碰读数与成员版本文件。
 */
function saveAlertState(path: string, state: AlertState): void {
  // 直接复用 store.ts 的原子写入实现风格,内联以保持本文件自包含的错误措辞。
  const { mkdirSync, renameSync, writeFileSync } = require('node:fs') as typeof import('node:fs');
  const { dirname } = require('node:path') as typeof import('node:path');
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}`;
  const body =
    JSON.stringify(
      {
        version: 2,
        ...state,
        rules: state.rules.map((r) => ({
          id: r.id,
          targetType: r.targetType,
          targetId: r.targetId,
          thresholdMilli: r.thresholdMilli.toString(),
        })),
      },
      null,
      2,
    ) + '\n';
  try {
    writeFileSync(tmp, body, 'utf8');
    renameSync(tmp, path);
  } catch (e) {
    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
  }
}

/**
 * 载入读数并取出指定设备的完整时序(按时刻排序)。
 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
 */
function deviceSeries(device: string): Reading[] {
  const all = loadStore(dataFilePath());
  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
  for (let i = 1; i < series.length; i++) {
    if (series[i].ts === series[i - 1].ts) {
      throw new StoreError(
        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
      );
    }
  }
  return series;
}

/**
 * 分组规则的评估环境:绑定分组与全库设备时序。
 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
 */
interface GroupEnv {
  kind: 'group';
  group: Group;
  byDevice: Map<string, Reading[]>;
}

interface DeviceEnv {
  kind: 'device';
  series: Reading[];
}

type RuleEnv = DeviceEnv | GroupEnv;

/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
function prepareEnv(rule: AlertRule): RuleEnv {
  if (rule.targetType === 'device') {
    return { kind: 'device', series: deviceSeries(rule.targetId) };
  }
  const groups = loadGroups(groupFilePath());
  const group = groups.find((g) => g.id === rule.targetId);
  if (!group) {
    throw new StoreError(
      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
    );
  }
  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
  return { kind: 'group', group, byDevice };
}

/** 不可判定原因(未知/异常覆盖秒数)。 */
function undecidableReason(stats: Pick<DayStats, 'unknown' | 'anomaly'>): string {
  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
}

/**
 * 计算规则在完整 UTC 日 [dayStart, dayStart+86400) 上的统计。
 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径。
 */
function computeRuleDay(rule: AlertRule, env: RuleEnv, dayStart: number): DayStats {
  const dayEnd = dayStart + DAY_SECONDS;
  if (env.kind === 'device') {
    return computeDay(env.series, dayStart, dayEnd);
  }
  const stats = computeGroupSegment(env.group.versions, env.byDevice, dayStart, dayEnd);
  return {
    valid: stats.valid,
    anomaly: stats.anomaly,
    unknown: stats.unknown,
    consumption: stats.consumption,
  };
}

/**
 * 创建规则。相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建;
 * 任一不同即报冲突。设备必须已有存储读数;分组必须已配置。返回进程退出码。
 */
export function cmdRuleCreate(opts: {
  id: string;
  targetType: RuleTargetType;
  targetId: string;
  thresholdMilli: bigint;
}): number {
  const statePath = alertFilePath();
  let state: AlertState;
  try {
    state = loadAlertState(statePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  const got = `${opts.targetType}=${opts.targetId}`;
  const existing = state.rules.find((r) => r.id === opts.id);
  if (existing) {
    if (
      existing.targetType === opts.targetType &&
      existing.targetId === opts.targetId &&
      existing.thresholdMilli === opts.thresholdMilli
    ) {
      console.log(
        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
          `threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
      );
      return 0;
    }
    err(
      `rule '${opts.id}' already exists with different parameters ` +
        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
    );
    return 1;
  }

  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
  try {
    if (opts.targetType === 'device') {
      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
      if (!devices.has(opts.targetId)) {
        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
        return 1;
      }
    } else {
      const groups = loadGroups(groupFilePath());
      if (!groups.some((g) => g.id === opts.targetId)) {
        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
        return 1;
      }
    }
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  state.rules.push({
    id: opts.id,
    targetType: opts.targetType,
    targetId: opts.targetId,
    thresholdMilli: opts.thresholdMilli,
  });
  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  console.log(
    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
  );
  return 0;
}

/** 列出全部规则(含目标类型)。只读。返回进程退出码。 */
export function cmdRuleList(): number {
  let state: AlertState;
  try {
    state = loadAlertState(alertFilePath());
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  if (state.rules.length === 0) {
    console.log('no rules defined');
    return 0;
  }
  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  for (const r of rules) {
    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
    console.log(
      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
    );
  }
  return 0;
}

/**
 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
 */
export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
  const statePath = alertFilePath();
  let state: AlertState;
  let rule: AlertRule;
  let env: RuleEnv;
  try {
    state = loadAlertState(statePath);
    const found = state.rules.find((r) => r.id === opts.ruleId);
    if (!found) {
      err(`unknown rule '${opts.ruleId}'`);
      return 1;
    }
    rule = found;
    env = prepareEnv(rule);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
  const alertIds = new Set(state.alerts.map((a) => a.id));

  const threshold = rule.thresholdMilli;
  const lines: string[] = [];
  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
    const date = formatIsoUtc(dayStart).slice(0, 10);
    const stats = computeRuleDay(rule, env, dayStart);
    if (stats.unknown > 0 || stats.anomaly > 0) {
      // 有未知或下降覆盖:不可判定,不触发也不恢复。
      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
      continue;
    }
    const exceeded = stats.consumption > threshold;
    const cmp =
      `consumption=${formatKwh(stats.consumption)} kWh ` +
      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
    const open = state.alerts.find(
      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
    );
    if (exceeded) {
      if (open) {
        // 重复超限:保留原标识,不新增事件。
        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
      } else {
        const id = `alert-${state.nextAlertNum++}`;
        if (alertIds.has(id)) {
          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
          return 1;
        }
        alertIds.add(id);
        state.alerts.push({
          id,
          ruleId: rule.id,
          date,
          status: 'triggered',
          acknowledged: false,
          events: [
            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
          ],
        });
        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
      }
    } else {
      if (open) {
        open.status = 'recovered';
        open.events.push({
          seq: state.nextEventSeq++,
          type: 'recovered',
          consumptionMilli: stats.consumption.toString(),
        });
        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
      } else {
        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
      }
    }
  }

  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  console.log(
    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
  );
  for (const line of lines) console.log(line);
  return 0;
}

/**
 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
 * 给定日期范围时逐日展示当前计算的消耗或不可判定原因及各次告警;省略范围时
 * 展示有告警记录的全部日期。触发/恢复事件中的消耗为评估当时记录,不随后续
 * 数据变化改写。返回进程退出码。
 */
export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
  let state: AlertState;
  let rule: AlertRule;
  let env: RuleEnv;
  try {
    state = loadAlertState(alertFilePath());
    const found = state.rules.find((r) => r.id === opts.ruleId);
    if (!found) {
      err(`unknown rule '${opts.ruleId}'`);
      return 1;
    }
    rule = found;
    env = prepareEnv(rule);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  let dayStarts: number[];
  if (opts.from !== undefined && opts.to !== undefined) {
    dayStarts = [];
    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
  } else {
    const dates = [
      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
    ].sort();
    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
  }

  console.log(
    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
  );
  if (dayStarts.length === 0) {
    console.log(`  no alerts recorded for rule '${rule.id}'`);
    return 0;
  }

  const threshold = rule.thresholdMilli;
  for (const dayStart of dayStarts) {
    const date = formatIsoUtc(dayStart).slice(0, 10);
    const stats = computeRuleDay(rule, env, dayStart);
    if (stats.unknown > 0 || stats.anomaly > 0) {
      console.log(`  ${date}  ${undecidableReason(stats)}`);
    } else {
      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
      console.log(
        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
      );
    }
    const alerts = state.alerts
      .filter((a) => a.ruleId === rule.id && a.date === date)
      .sort((a, b) => a.events[0].seq - b.events[0].seq);
    if (alerts.length === 0) {
      console.log('    no alerts');
      continue;
    }
    for (const a of alerts) {
      console.log(
        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
      );
      const events = a.events
        .map((e) => {
          const consumption =
            e.consumptionMilli !== undefined
              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
              : '';
          return `#${e.seq} ${e.type}${consumption}`;
        })
        .join(', ');
      console.log(`      events: ${events}`);
    }
  }
  return 0;
}

/**
 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
 * 确认不改变超限或恢复状态。返回进程退出码。
 */
export function cmdAck(alertId: string): number {
  const statePath = alertFilePath();
  let state: AlertState;
  try {
    state = loadAlertState(statePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const alert = state.alerts.find((a) => a.id === alertId);
  if (!alert) {
    err(`unknown alert '${alertId}'`);
    return 1;
  }
  if (alert.acknowledged) {
    console.log(`alert ${alert.id} already acknowledged; unchanged`);
    return 0;
  }
  alert.acknowledged = true;
  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
  try {
    saveAlertState(statePath, state);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const rule = state.rules.find((r) => r.id === alert.ruleId);
  const target = rule ? ` ${targetLabel(rule)}` : '';
  console.log(
    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
  );
  return 0;
}

